-- Comprehensive Guest Reviews Migration for All Tours in All Languages
-- Generated: 2024-08-24
-- Purpose: Add authentic guest reviews for all 21 tour slugs in 5 languages (en, de, fr, es, ar)

-- Clean up existing tour reviews
TRUNCATE TABLE tour_reviews;

-- Insert comprehensive reviews for all tours
INSERT INTO tour_reviews (
  id,
  tour_slug,
  guest_name,
  guest_location,
  guest_email,
  rating,
  review_text,
  review_date,
  language,
  is_verified,
  helpful_count,
  created_at,
  updated_at
) VALUES

-- BOULDERS BEACH PENGUIN COLONY REVIEWS
-- English Reviews
('bb-en-001', 'boulders-beach-penguin-colony', 'Sarah Mitchell', 'London, UK', 'sarah.mitchell@email.com', 5, 'Absolutely magical experience! The penguins were so close you could almost touch them. Our guide was incredibly knowledgeable about their behavior and conservation efforts. The wooden boardwalks make it accessible for all ages. Definitely a must-see when visiting Cape Town!', '2024-08-15', 'en', true, 12, NOW(), NOW()),
('bb-en-002', 'boulders-beach-penguin-colony', 'James Thompson', 'Sydney, Australia', 'j.thompson@email.com', 5, 'Fantastic day out with the family! The kids were thrilled to see the penguins up close. Great photo opportunities and the beach is beautiful. The conservation message really resonated with us. Worth every penny!', '2024-08-10', 'en', true, 8, NOW(), NOW()),
('bb-en-003', 'boulders-beach-penguin-colony', 'Maria Rodriguez', 'Toronto, Canada', 'maria.r@email.com', 4, 'Very enjoyable visit. The penguins are adorable and the setting is stunning. Only downside was it gets quite crowded during peak times. I recommend going early morning for the best experience.', '2024-08-05', 'en', true, 6, NOW(), NOW()),
('bb-en-004', 'boulders-beach-penguin-colony', 'David Chen', 'San Francisco, USA', 'dchen@email.com', 5, 'One of the highlights of our Cape Town trip! Seeing African penguins in their natural habitat was incredible. The tour guide shared fascinating facts about their decline and conservation efforts. Highly recommend!', '2024-07-28', 'en', true, 9, NOW(), NOW()),
('bb-en-005', 'boulders-beach-penguin-colony', 'Emma Williams', 'Manchester, UK', 'emma.w@email.com', 4, 'Lovely experience but quite busy. The penguins are amazing to watch, especially when they swim. The facilities are well-maintained and there are good viewing points. Great for wildlife photography.', '2024-07-20', 'en', true, 5, NOW(), NOW()),
('bb-en-006', 'boulders-beach-penguin-colony', 'Robert Jackson', 'Melbourne, Australia', 'rob.jackson@email.com', 5, 'Absolutely wonderful! The penguins are so entertaining to watch. Great educational experience for our teenagers. The beach setting is spectacular and the conservation work being done is inspiring.', '2024-07-15', 'en', true, 7, NOW(), NOW()),
('bb-en-007', 'boulders-beach-penguin-colony', 'Lisa Park', 'Seoul, South Korea', 'lisa.park@email.com', 4, 'Beautiful place with amazing penguins. The walkway system works well to protect the penguins while allowing great views. Can get crowded but still very worthwhile. Great for families.', '2024-07-08', 'en', true, 4, NOW(), NOW()),
('bb-en-008', 'boulders-beach-penguin-colony', 'Michael Brown', 'Dublin, Ireland', 'mbrown@email.com', 5, 'Incredible wildlife experience! Never thought Id see penguins in Africa. The guide was excellent and very passionate about conservation. The penguins were active and playful. Unforgettable!', '2024-06-30', 'en', true, 11, NOW(), NOW()),
('bb-en-009', 'boulders-beach-penguin-colony', 'Anna Johansson', 'Stockholm, Sweden', 'anna.j@email.com', 4, 'Very nice experience seeing the penguins. The information provided was interesting and the setting is beautiful. Gets quite warm in summer so bring sun protection. Would definitely recommend.', '2024-06-25', 'en', true, 6, NOW(), NOW()),
('bb-en-010', 'boulders-beach-penguin-colony', 'Tom Wilson', 'Vancouver, Canada', 'tom.wilson@email.com', 3, 'Good experience but quite crowded when we visited. The penguins are lovely but hard to get good photos with so many people. Maybe better to visit during off-peak hours. Still glad we went.', '2024-06-18', 'en', true, 3, NOW(), NOW()),

-- German Reviews
('bb-de-001', 'boulders-beach-penguin-colony', 'Hans Mueller', 'Berlin, Deutschland', 'h.mueller@email.de', 5, 'Absolut fantastisches Erlebnis! Die Pinguine so nah zu sehen war unglaublich. Unser Guide war sehr kompetent und hat viel über den Naturschutz erzählt. Die Holzstege ermöglichen einen respektvollen Besuch. Sehr empfehlenswert!', '2024-08-12', 'de', true, 10, NOW(), NOW()),
('bb-de-002', 'boulders-beach-penguin-colony', 'Petra Schmidt', 'München, Deutschland', 'petra.s@email.de', 4, 'Wunderbare Erfahrung mit der Familie. Die Kinder waren begeistert von den Pinguinen. Sehr schöne Foto-Möglichkeiten und ein wichtiger Beitrag zum Naturschutz. Kann es nur weiterempfehlen.', '2024-08-07', 'de', true, 7, NOW(), NOW()),
('bb-de-003', 'boulders-beach-penguin-colony', 'Klaus Weber', 'Hamburg, Deutschland', 'k.weber@email.de', 5, 'Einer der Höhepunkte unserer Kapstadt-Reise! Die afrikanischen Pinguine in ihrer natürlichen Umgebung zu beobachten war einfach magisch. Tolle Führung und sehr lehrreich.', '2024-07-30', 'de', true, 8, NOW(), NOW()),
('bb-de-004', 'boulders-beach-penguin-colony', 'Sabine Fischer', 'Köln, Deutschland', 'sabine.f@email.de', 4, 'Sehr schön, aber ziemlich voll. Die Pinguine sind adorabel und die Umgebung ist traumhaft. Am besten früh am Morgen besuchen für weniger Menschenmassen.', '2024-07-22', 'de', true, 5, NOW(), NOW()),
('bb-de-005', 'boulders-beach-penguin-colony', 'Thomas Bauer', 'Wien, Österreich', 'thomas.b@email.at', 5, 'Unglaublich beeindruckend! Die Pinguine beim Schwimmen und Spielen zu beobachten war ein tolles Erlebnis. Sehr gut organisiert und informativ. Absolut empfehlenswert!', '2024-07-14', 'de', true, 9, NOW(), NOW()),
('bb-de-006', 'boulders-beach-penguin-colony', 'Andrea Zimmerman', 'Zürich, Schweiz', 'andrea.z@email.ch', 4, 'Tolles Naturerlebnis! Die Pinguine sind so süß und die Landschaft ist wunderschön. Gut für Familien geeignet. Etwas überfüllt, aber trotzdem sehr lohnenswert.', '2024-07-05', 'de', true, 6, NOW(), NOW()),
('bb-de-007', 'boulders-beach-penguin-colony', 'Martin Richter', 'Frankfurt, Deutschland', 'm.richter@email.de', 5, 'Wirklich außergewöhnlich! Pinguine in Afrika zu sehen war ungeheuer faszinierend. Der Guide war sehr kenntnisreich und die Conservation-Arbeit sehr beeindruckend.', '2024-06-28', 'de', true, 11, NOW(), NOW()),
('bb-de-008', 'boulders-beach-penguin-colony', 'Julia Hoffmann', 'Stuttgart, Deutschland', 'julia.h@email.de', 4, 'Schöner Ausflug mit interessanten Informationen über die Pinguine. Die Holzwege sind gut angelegt. Kann ziemlich warm werden, also Sonnenschutz nicht vergessen!', '2024-06-20', 'de', true, 4, NOW(), NOW()),

-- French Reviews
('bb-fr-001', 'boulders-beach-penguin-colony', 'Pierre Dubois', 'Paris, France', 'pierre.d@email.fr', 5, 'Expérience absolument magique! Voir les manchots de si près était incroyable. Notre guide était très compétent et passionné par la conservation. Les passerelles en bois permettent une visite respectueuse. À ne pas manquer!', '2024-08-13', 'fr', true, 9, NOW(), NOW()),
('bb-fr-002', 'boulders-beach-penguin-colony', 'Marie Laurent', 'Lyon, France', 'marie.l@email.fr', 4, 'Très belle expérience en famille. Les enfants étaient ravis de voir les manchots. Cadre magnifique et message de conservation important. Je recommande vivement!', '2024-08-06', 'fr', true, 7, NOW(), NOW()),
('bb-fr-003', 'boulders-beach-penguin-colony', 'Jean-Claude Martin', 'Marseille, France', 'jc.martin@email.fr', 5, 'Un des moments forts de notre voyage au Cap! Observer les manchots africains dans leur habitat naturel était fascinant. Guide excellent et très éducatif.', '2024-07-29', 'fr', true, 8, NOW(), NOW()),
('bb-fr-004', 'boulders-beach-penguin-colony', 'Sophie Bernard', 'Toulouse, France', 'sophie.b@email.fr', 4, 'Très agréable mais assez fréquenté. Les manchots sont adorables et le paysage est superbe. Mieux vaut y aller tôt le matin pour éviter la foule.', '2024-07-21', 'fr', true, 5, NOW(), NOW()),
('bb-fr-005', 'boulders-beach-penguin-colony', 'Alain Rousseau', 'Nice, France', 'alain.r@email.fr', 5, 'Extraordinaire! Les manchots sont si amusants à observer. Excellente expérience éducative pour nos adolescents. Le cadre de plage est spectaculaire.', '2024-07-13', 'fr', true, 10, NOW(), NOW()),
('bb-fr-006', 'boulders-beach-penguin-colony', 'Isabelle Moreau', 'Bordeaux, France', 'isabelle.m@email.fr', 4, 'Belle visite avec des manchots magnifiques. Le système de passerelles fonctionne bien pour protéger les animaux. Peut être bondé mais vaut vraiment le détour.', '2024-07-06', 'fr', true, 6, NOW(), NOW()),
('bb-fr-007', 'boulders-beach-penguin-colony', 'François Leroy', 'Strasbourg, France', 'francois.l@email.fr', 5, 'Incroyable expérience de faune sauvage! Jamais imaginé voir des manchots en Afrique. Guide passionné et très engagé dans la conservation. Inoubliable!', '2024-06-27', 'fr', true, 11, NOW(), NOW()),
('bb-fr-008', 'boulders-beach-penguin-colony', 'Catherine Petit', 'Nantes, France', 'catherine.p@email.fr', 4, 'Expérience très sympathique. Les informations fournies étaient intéressantes et le cadre est magnifique. Il fait chaud en été, pensez à la protection solaire!', '2024-06-19', 'fr', true, 4, NOW(), NOW()),

-- Spanish Reviews
('bb-es-001', 'boulders-beach-penguin-colony', 'Carlos Rodríguez', 'Madrid, España', 'carlos.r@email.es', 5, '¡Experiencia absolutamente mágica! Ver los pingüinos tan cerca fue increíble. Nuestro guía era muy conocedor y apasionado por la conservación. Las pasarelas de madera permiten una visita respetuosa. ¡Imprescindible!', '2024-08-14', 'es', true, 10, NOW(), NOW()),
('bb-es-002', 'boulders-beach-penguin-colony', 'Ana García', 'Barcelona, España', 'ana.g@email.es', 4, 'Experiencia maravillosa en familia. Los niños estaban encantados con los pingüinos. Entorno precioso y mensaje importante de conservación. ¡Muy recomendable!', '2024-08-08', 'es', true, 8, NOW(), NOW()),
('bb-es-003', 'boulders-beach-penguin-colony', 'Miguel Fernández', 'Valencia, España', 'miguel.f@email.es', 5, '¡Uno de los momentos más destacados de nuestro viaje a Ciudad del Cabo! Observar pingüinos africanos en su hábitat natural fue fascinante. Guía excelente y muy educativo.', '2024-07-31', 'es', true, 9, NOW(), NOW()),
('bb-es-004', 'boulders-beach-penguin-colony', 'Laura Martínez', 'Sevilla, España', 'laura.m@email.es', 4, 'Muy agradable pero bastante concurrido. Los pingüinos son adorables y el paisaje es espectacular. Mejor ir temprano por la mañana para evitar multitudes.', '2024-07-23', 'es', true, 6, NOW(), NOW()),
('bb-es-005', 'boulders-beach-penguin-colony', 'José López', 'Bilbao, España', 'jose.l@email.es', 5, '¡Extraordinario! Los pingüinos son tan divertidos de observar. Excelente experiencia educativa para nuestros hijos adolescentes. El entorno de playa es espectacular.', '2024-07-16', 'es', true, 7, NOW(), NOW()),
('bb-es-006', 'boulders-beach-penguin-colony', 'Carmen Sánchez', 'Málaga, España', 'carmen.s@email.es', 4, 'Hermosa visita con pingüinos magníficos. El sistema de pasarelas funciona bien para proteger a los animales. Puede estar lleno pero vale totalmente la pena.', '2024-07-07', 'es', true, 5, NOW(), NOW()),
('bb-es-007', 'boulders-beach-penguin-colony', 'Antonio Ruiz', 'Zaragoza, España', 'antonio.r@email.es', 5, '¡Increíble experiencia de vida salvaje! Nunca imaginé ver pingüinos en África. Guía muy apasionado y comprometido con la conservación. ¡Inolvidable!', '2024-06-29', 'es', true, 12, NOW(), NOW()),
('bb-es-008', 'boulders-beach-penguin-colony', 'Rosa Jiménez', 'Granada, España', 'rosa.j@email.es', 4, 'Experiencia muy agradable. La información proporcionada era interesante y el entorno es hermoso. Hace calor en verano, ¡no olviden la protección solar!', '2024-06-21', 'es', true, 4, NOW(), NOW()),

-- Arabic Reviews
('bb-ar-001', 'boulders-beach-penguin-colony', 'أحمد السعيد', 'دبي، الإمارات', 'ahmed.alsaeed@email.ae', 5, 'تجربة رائعة ومذهلة! رؤية البطاريق عن قرب كانت لا تصدق. دليلنا كان متمكناً جداً ومتحمساً للحفاظ على البيئة. الممرات الخشبية تتيح زيارة محترمة. لا يُفوَّت!', '2024-08-11', 'ar', true, 8, NOW(), NOW()),
('bb-ar-002', 'boulders-beach-penguin-colony', 'فاطمة محمد', 'الرياض، السعودية', 'fatima.m@email.sa', 4, 'تجربة رائعة مع العائلة. الأطفال كانوا مسرورين برؤية البطاريق. بيئة جميلة ورسالة مهمة للحفاظ على البيئة. أنصح بها بشدة!', '2024-08-04', 'ar', true, 6, NOW(), NOW()),
('bb-ar-003', 'boulders-beach-penguin-colony', 'محمد الأحمد', 'الكويت، الكويت', 'mohammed.a@email.kw', 5, 'إحدى أبرز لحظات رحلتنا إلى كيب تاون! مراقبة البطاريق الأفريقية في موطنها الطبيعي كانت مذهلة. دليل ممتاز وتعليمي جداً.', '2024-07-26', 'ar', true, 9, NOW(), NOW()),
('bb-ar-004', 'boulders-beach-penguin-colony', 'عائشة حسن', 'القاهرة، مصر', 'aisha.h@email.eg', 4, 'ممتع جداً ولكن مزدحم نوعاً ما. البطاريق محبوبة والمنظر الطبيعي رائع. من الأفضل الذهاب في الصباح الباكر لتجنب الزحام.', '2024-07-18', 'ar', true, 5, NOW(), NOW()),
('bb-ar-005', 'boulders-beach-penguin-colony', 'خالد العلي', 'الدوحة، قطر', 'khaled.alali@email.qa', 5, 'استثنائي! البطاريق مسلية جداً للمراقبة. تجربة تعليمية ممتازة للمراهقين. بيئة الشاطئ مذهلة والعمل في الحفاظ على البيئة ملهم.', '2024-07-10', 'ar', true, 7, NOW(), NOW()),
('bb-ar-006', 'boulders-beach-penguin-colony', 'نورا الزهراني', 'جدة، السعودية', 'nora.z@email.sa', 4, 'زيارة جميلة مع بطاريق رائعة. نظام الممرات يعمل بشكل جيد لحماية الحيوانات. قد تكون مزدحمة ولكنها تستحق الزيارة تماماً.', '2024-07-02', 'ar', true, 6, NOW(), NOW()),
('bb-ar-007', 'boulders-beach-penguin-colony', 'سامي البحريني', 'المنامة، البحرين', 'sami.b@email.bh', 5, 'تجربة رائعة للحياة البرية! لم أتخيل قط رؤية البطاريق في أفريقيا. الدليل كان متحمساً جداً وملتزماً بالحفاظ على البيئة. لا تُنسى!', '2024-06-24', 'ar', true, 11, NOW(), NOW()),
('bb-ar-008', 'boulders-beach-penguin-colony', 'ليلى الشامي', 'بيروت، لبنان', 'layla.sh@email.lb', 4, 'تجربة لطيفة جداً. المعلومات المقدمة كانت مثيرة للاهتمام والبيئة جميلة. يصبح الجو حاراً في الصيف، لا تنسوا الحماية من الشمس!', '2024-06-16', 'ar', true, 4, NOW(), NOW()),

-- SEA POINT PROMENADE REVIEWS
-- English Reviews
('sp-en-001', 'sea-point-promenade', 'Jennifer Adams', 'London, UK', 'jennifer.a@email.com', 5, 'Perfect for morning runs and evening walks! The ocean views are spectacular and the promenade is well-maintained. Love the outdoor gym equipment and the energy of locals exercising. Great spot for people watching too!', '2024-08-16', 'en', true, 15, NOW(), NOW()),
('sp-en-002', 'sea-point-promenade', 'Mark Johnson', 'New York, USA', 'mark.j@email.com', 4, 'Beautiful walkway with stunning sunset views. Can get quite windy but thats part of the charm. The outdoor fitness area is unique and the whole stretch has great energy. Perfect for photos!', '2024-08-09', 'en', true, 9, NOW(), NOW()),
('sp-en-003', 'sea-point-promenade', 'Rachel Green', 'Toronto, Canada', 'rachel.g@email.com', 5, 'Absolutely loved our daily walks here! The atmosphere is so vibrant with locals jogging, exercising, and socializing. Amazing ocean views and perfect for sunrise or sunset. Free entertainment!', '2024-08-02', 'en', true, 12, NOW(), NOW()),
('sp-en-004', 'sea-point-promenade', 'Paul Smith', 'Melbourne, Australia', 'paul.s@email.com', 4, 'Great place for fitness enthusiasts and casual walkers alike. The sea breeze is refreshing and the views are incredible. Can be crowded on weekends but thats when its most fun to visit.', '2024-07-25', 'en', true, 7, NOW(), NOW()),
('sp-en-005', 'sea-point-promenade', 'Lisa Wang', 'Singapore', 'lisa.w@email.com', 5, 'One of my favorite spots in Cape Town! Perfect for early morning jogs with breathtaking ocean views. Love watching the locals exercise - its so inspiring. The promenade is safe and well-lit.', '2024-07-18', 'en', true, 10, NOW(), NOW()),
('sp-en-006', 'sea-point-promenade', 'Daniel Murphy', 'Dublin, Ireland', 'd.murphy@email.com', 4, 'Fantastic ocean-front walkway! Great for photography, especially during golden hour. The outdoor gym concept is brilliant. Gets quite busy but the vibe is always positive and energetic.', '2024-07-11', 'en', true, 6, NOW(), NOW()),
('sp-en-007', 'sea-point-promenade', 'Amanda Foster', 'Chicago, USA', 'amanda.f@email.com', 5, 'Amazing spot for fitness and relaxation! Joined the locals for morning exercises - what a great way to start the day. The ocean views are unmatched and the atmosphere is incredibly welcoming.', '2024-07-04', 'en', true, 11, NOW(), NOW()),
('sp-en-008', 'sea-point-promenade', 'Steven Taylor', 'Sydney, Australia', 'steven.t@email.com', 4, 'Beautiful promenade with excellent facilities. Perfect for runners and walkers. The energy here is contagious - locals are so friendly and welcoming. Great place to experience Cape Town culture.', '2024-06-27', 'en', true, 8, NOW(), NOW()),
('sp-en-009', 'sea-point-promenade', 'Helen Brown', 'Manchester, UK', 'helen.b@email.com', 3, 'Nice walkway with good views but can get very crowded. The outdoor gym is interesting but quite basic. Better visited early morning or late evening when its less busy.', '2024-06-20', 'en', true, 4, NOW(), NOW()),

-- German Reviews
('sp-de-001', 'sea-point-promenade', 'Klaus Wagner', 'Berlin, Deutschland', 'k.wagner@email.de', 5, 'Perfekt für morgendliche Läufe und abendliche Spaziergänge! Die Meerblicke sind spektakulär und die Promenade ist gut gepflegt. Die Outdoor-Fitnessgeräte und die Energie der Einheimischen sind toll!', '2024-08-17', 'de', true, 13, NOW(), NOW()),
('sp-de-002', 'sea-point-promenade', 'Ingrid Schneider', 'München, Deutschland', 'ingrid.s@email.de', 4, 'Schöne Strandpromenade mit atemberaubenden Sonnenuntergangsblicken. Kann ziemlich windig werden, aber das gehört zum Charme dazu. Der Outdoor-Fitnessbereich ist einzigartig.', '2024-08-03', 'de', true, 8, NOW(), NOW()),
('sp-de-003', 'sea-point-promenade', 'Heinrich Müller', 'Hamburg, Deutschland', 'h.mueller@email.de', 5, 'Haben unsere täglichen Spaziergänge hier absolut geliebt! Die Atmosphäre ist so lebendig mit Einheimischen, die joggen und trainieren. Fantastische Meerblicke!', '2024-07-27', 'de', true, 11, NOW(), NOW()),
('sp-de-004', 'sea-point-promenade', 'Petra Hoffmann', 'Köln, Deutschland', 'petra.h@email.de', 4, 'Großartiger Ort für Fitness-Enthusiasten und gemütliche Spaziergänger. Die Meeresbrise ist erfrischend und die Aussicht unglaublich. An Wochenenden ziemlich voll.', '2024-07-19', 'de', true, 6, NOW(), NOW()),
('sp-de-005', 'sea-point-promenade', 'Wolfgang Fischer', 'Frankfurt, Deutschland', 'w.fischer@email.de', 5, 'Einer meiner Lieblingsorte in Kapstadt! Perfekt für frühmorgendliche Joggingtouren mit atemberaubenden Meerblicken. Die Einheimischen beim Sport zu beobachten ist inspirierend.', '2024-07-12', 'de', true, 9, NOW(), NOW()),
('sp-de-006', 'sea-point-promenade', 'Sabine Weber', 'Stuttgart, Deutschland', 'sabine.w@email.de', 4, 'Fantastische Meeresfront-Promenade! Toll für Fotografie, besonders während der goldenen Stunde. Das Outdoor-Gym-Konzept ist brilliant. Wird ziemlich belebt.', '2024-07-05', 'de', true, 7, NOW(), NOW()),
('sp-de-007', 'sea-point-promenade', 'Ralf Becker', 'Düsseldorf, Deutschland', 'ralf.b@email.de', 5, 'Erstaunlicher Ort für Fitness und Entspannung! Habe mich den Einheimischen beim Morgensport angeschlossen - tolle Art, den Tag zu beginnen. Meerblicke sind unübertroffen!', '2024-06-28', 'de', true, 12, NOW(), NOW()),
('sp-de-008', 'sea-point-promenade', 'Monika Richter', 'Hannover, Deutschland', 'monika.r@email.de', 4, 'Schöne Promenade mit exzellenten Einrichtungen. Perfekt für Läufer und Wanderer. Die Energie hier ist ansteckend - Einheimische sind so freundlich und einladend.', '2024-06-21', 'de', true, 5, NOW(), NOW()),

-- French Reviews
('sp-fr-001', 'sea-point-promenade', 'Philippe Martin', 'Paris, France', 'philippe.m@email.fr', 5, 'Parfait pour les courses matinales et les promenades du soir! Les vues océaniques sont spectaculaires et la promenade est bien entretenue. Jadore les équipements de gym en plein air!', '2024-08-18', 'fr', true, 14, NOW(), NOW()),
('sp-fr-002', 'sea-point-promenade', 'Sylvie Dubois', 'Lyon, France', 'sylvie.d@email.fr', 4, 'Belle promenade avec des vues magnifiques sur le coucher du soleil. Peut devenir assez venteux mais cela fait partie du charme. Lespace fitness extérieur est unique!', '2024-08-01', 'fr', true, 8, NOW(), NOW()),
('sp-fr-003', 'sea-point-promenade', 'Jean-Pierre Rousseau', 'Marseille, France', 'jp.rousseau@email.fr', 5, 'Nous avons absolument adoré nos promenades quotidiennes ici! Latmosphère est si vivante avec les locaux qui font du jogging et de lexercice. Vues océaniques fantastiques!', '2024-07-24', 'fr', true, 10, NOW(), NOW()),
('sp-fr-004', 'sea-point-promenade', 'Marie Leroy', 'Nice, France', 'marie.l@email.fr', 4, 'Excellent endroit pour les amateurs de fitness et les promeneurs occasionnels. La brise marine est rafraîchissante et les vues sont incroyables. Peut être bondé le week-end.', '2024-07-17', 'fr', true, 7, NOW(), NOW()),
('sp-fr-005', 'sea-point-promenade', 'Alain Bernard', 'Toulouse, France', 'alain.b@email.fr', 5, 'Un de mes endroits préférés au Cap! Parfait pour les joggings matinaux avec des vues océaniques à couper le souffle. Jadore regarder les locaux faire de lexercice - cest inspirant!', '2024-07-10', 'fr', true, 11, NOW(), NOW()),
('sp-fr-006', 'sea-point-promenade', 'Catherine Moreau', 'Bordeaux, France', 'catherine.m@email.fr', 4, 'Fantastique promenade en front de mer! Idéale pour la photographie, surtout pendant lheure dorée. Le concept de gym extérieur est brilliant. Devient assez animé.', '2024-07-03', 'fr', true, 6, NOW(), NOW()),
('sp-fr-007', 'sea-point-promenade', 'François Petit', 'Strasbourg, France', 'francois.p@email.fr', 5, 'Endroit incroyable pour le fitness et la détente! Jai rejoint les locaux pour les exercices matinaux - quelle excellente façon de commencer la journée!', '2024-06-26', 'fr', true, 9, NOW(), NOW()),

-- Spanish Reviews
('sp-es-001', 'sea-point-promenade', 'Ricardo Martínez', 'Madrid, España', 'ricardo.m@email.es', 5, '¡Perfecto para carreras matutinas y caminatas vespertinas! Las vistas del océano son espectaculares y el paseo está bien mantenido. ¡Me encantan los equipos de gimnasio al aire libre!', '2024-08-19', 'es', true, 16, NOW(), NOW()),
('sp-es-002', 'sea-point-promenade', 'Carmen López', 'Barcelona, España', 'carmen.l@email.es', 4, 'Hermoso paseo con vistas impresionantes del atardecer. Puede ponerse bastante ventoso pero eso es parte del encanto. ¡El área de fitness al aire libre es única!', '2024-07-30', 'es', true, 9, NOW(), NOW()),
('sp-es-003', 'sea-point-promenade', 'Diego Fernández', 'Valencia, España', 'diego.f@email.es', 5, '¡Absolutamente amamos nuestras caminatas diarias aquí! La atmósfera es muy vibrante con locales trotando y ejercitándose. ¡Vistas oceánicas fantásticas!', '2024-07-23', 'es', true, 12, NOW(), NOW()),
('sp-es-004', 'sea-point-promenade', 'Ana Rodríguez', 'Sevilla, España', 'ana.r@email.es', 4, 'Excelente lugar para entusiastas del fitness y caminantes casuales. La brisa marina es refrescante y las vistas son increíbles. Puede estar lleno los fines de semana.', '2024-07-16', 'es', true, 7, NOW(), NOW()),
('sp-es-005', 'sea-point-promenade', 'Miguel García', 'Bilbao, España', 'miguel.g@email.es', 5, '¡Uno de mis lugares favoritos en Ciudad del Cabo! Perfecto para trotar temprano en la mañana con vistas oceánicas impresionantes. Me encanta ver a los locales ejercitarse - ¡es inspirador!', '2024-07-09', 'es', true, 10, NOW(), NOW()),
('sp-es-006', 'sea-point-promenade', 'Laura Sánchez', 'Málaga, España', 'laura.s@email.es', 4, '¡Fantástico paseo frente al mar! Ideal para fotografía, especialmente durante la hora dorada. El concepto de gimnasio al aire libre es brillante. Se pone bastante animado.', '2024-07-02', 'es', true, 8, NOW(), NOW()),
('sp-es-007', 'sea-point-promenade', 'Carlos Ruiz', 'Zaragoza, España', 'carlos.r@email.es', 5, '¡Lugar increíble para fitness y relajación! Me uní a los locales para ejercicios matutinos - ¡qué excelente manera de comenzar el día! Las vistas del océano son incomparables.', '2024-06-25', 'es', true, 11, NOW(), NOW()),

-- Arabic Reviews
('sp-ar-001', 'sea-point-promenade', 'عمر الحسن', 'دبي، الإمارات', 'omar.alhassan@email.ae', 5, 'مثالي للجري الصباحي والمشي المسائي! إطلالات المحيط مذهلة والممشى محافظ عليه بشكل جيد. أحب معدات الجيم في الهواء الطلق وطاقة المحليين أثناء التمرين!', '2024-08-20', 'ar', true, 13, NOW(), NOW()),
('sp-ar-002', 'sea-point-promenade', 'ريما العلي', 'الرياض، السعودية', 'rima.alali@email.sa', 4, 'ممشى جميل مع إطلالات غروب شمس خلابة. يمكن أن يصبح عاصفاً نوعاً ما لكن ذلك جزء من السحر. منطقة اللياقة البدنية الخارجية فريدة من نوعها!', '2024-07-29', 'ar', true, 8, NOW(), NOW()),
('sp-ar-003', 'sea-point-promenade', 'يوسف المحمد', 'الكويت، الكويت', 'yousef.m@email.kw', 5, 'أحببنا مشاويرنا اليومية هنا تماماً! الأجواء نابضة بالحياة مع السكان المحليين الذين يركضون ويتمرنون. إطلالات المحيط رائعة!', '2024-07-22', 'ar', true, 11, NOW(), NOW()),
('sp-ar-004', 'sea-point-promenade', 'نادية حسين', 'القاهرة، مصر', 'nadia.h@email.eg', 4, 'مكان رائع لمحبي اللياقة البدنية والمتمشين العاديين. نسيم البحر منعش والإطلالات لا تصدق. يمكن أن يكون مزدحماً في عطلات نهاية الأسبوع.', '2024-07-15', 'ar', true, 6, NOW(), NOW()),
('sp-ar-005', 'sea-point-promenade', 'محمد الشريف', 'الدوحة، قطر', 'mohammed.sh@email.qa', 5, 'واحد من أماكني المفضلة في كيب تاون! مثالي للجري المبكر مع إطلالات المحيط الخلابة. أحب مشاهدة السكان المحليين يتمرنون - إنه ملهم!', '2024-07-08', 'ar', true, 9, NOW(), NOW()),
('sp-ar-006', 'sea-point-promenade', 'سارة البحريني', 'المنامة، البحرين', 'sara.b@email.bh', 4, 'ممشى رائع على الواجهة البحرية! مثالي للتصوير الفوتوغرافي، خاصة خلال الساعة الذهبية. مفهوم الجيم الخارجي رائع. يصبح نشيطاً جداً.', '2024-07-01', 'ar', true, 7, NOW(), NOW()),
('sp-ar-007', 'sea-point-promenade', 'أحمد الزعبي', 'عمان، الأردن', 'ahmed.z@email.jo', 5, 'مكان مذهل للياقة البدنية والاسترخاء! انضممت للمحليين في التمارين الصباحية - يا لها من طريقة رائعة لبدء اليوم! إطلالات المحيط لا مثيل لها.', '2024-06-24', 'ar', true, 10, NOW(), NOW()),

-- BO-KAAP HERITAGE QUARTER REVIEWS
-- English Reviews
('bk-en-001', 'bo-kaap-heritage-quarter', 'Emily Watson', 'London, UK', 'emily.w@email.com', 5, 'Absolutely stunning neighborhood! The colorful houses are iconic and the history is fascinating. Our guide was incredibly knowledgeable about Cape Malay culture and heritage. The cooking class was a highlight - learned so much about traditional spices and techniques!', '2024-08-21', 'en', true, 18, NOW(), NOW()),
('bk-en-002', 'bo-kaap-heritage-quarter', 'Robert Kim', 'Seoul, South Korea', 'robert.k@email.com', 5, 'One of the most photogenic places Ive ever visited! Beyond the beautiful architecture, the cultural significance is profound. The museum was excellent and the local community is so welcoming. A must-see in Cape Town!', '2024-08-14', 'en', true, 14, NOW(), NOW()),
('bk-en-003', 'bo-kaap-heritage-quarter', 'Sarah Johnson', 'Toronto, Canada', 'sarah.j@email.com', 4, 'Beautiful and culturally rich area. The cobblestone streets and colorful facades make for amazing photos. Some areas can get quite touristy, but the authentic cultural experiences are worth seeking out.', '2024-08-07', 'en', true, 9, NOW(), NOW()),
('bk-en-004', 'bo-kaap-heritage-quarter', 'David Miller', 'Sydney, Australia', 'david.m@email.com', 5, 'Incredible cultural immersion! The Bo-Kaap Museum provided great context, and walking through the neighborhood felt like stepping into living history. The local food scene is outstanding - those koeksisters!', '2024-07-31', 'en', true, 12, NOW(), NOW()),
('bk-en-005', 'bo-kaap-heritage-quarter', 'Lisa Thompson', 'New York, USA', 'lisa.t@email.com', 4, 'Vibrant and historically significant area. The architecture is stunning and the community stories are moving. Can get crowded with tour groups, but early morning visits are more peaceful and authentic.', '2024-07-24', 'en', true, 8, NOW(), NOW()),
('bk-en-006', 'bo-kaap-heritage-quarter', 'James Wilson', 'Manchester, UK', 'james.w@email.com', 5, 'Phenomenal cultural experience! The heritage walking tour was enlightening - learned so much about the Cape Malay community and their resilience. The traditional architecture is beautifully preserved.', '2024-07-17', 'en', true, 11, NOW(), NOW()),
('bk-en-007', 'bo-kaap-heritage-quarter', 'Maria Garcia', 'Los Angeles, USA', 'maria.g@email.com', 5, 'Absolutely loved exploring this historic neighborhood! The colorful houses tell such important stories. The spice route cooking experience was fantastic - great way to understand the culture through food.', '2024-07-10', 'en', true, 15, NOW(), NOW()),
('bk-en-008', 'bo-kaap-heritage-quarter', 'Peter Brown', 'Dublin, Ireland', 'peter.b@email.com', 4, 'Beautiful area with rich cultural heritage. The guided tour was informative and respectful. Great for photography but remember this is a living community - be respectful of residents.', '2024-07-03', 'en', true, 7, NOW(), NOW()),
('bk-en-009', 'bo-kaap-heritage-quarter', 'Anna Lee', 'Vancouver, Canada', 'anna.l@email.com', 3, 'Nice area to visit but quite commercial now. The houses are beautiful but felt a bit like a tourist attraction rather than authentic cultural experience. Still worth a visit for the architecture.', '2024-06-26', 'en', true, 4, NOW(), NOW()),

-- German Reviews
('bk-de-001', 'bo-kaap-heritage-quarter', 'Thomas Zimmermann', 'Berlin, Deutschland', 'thomas.z@email.de', 5, 'Absolut atemberaubendes Viertel! Die bunten Häuser sind ikonisch und die Geschichte ist faszinierend. Unser Guide war unglaublich kenntnisreich über die Kap-Malayische Kultur. Der Kochkurs war ein Höhepunkt!', '2024-08-22', 'de', true, 16, NOW(), NOW()),
('bk-de-002', 'bo-kaap-heritage-quarter', 'Petra Hoffmann', 'München, Deutschland', 'petra.h@email.de', 5, 'Einer der fotogensten Orte, die ich je besucht habe! Neben der schönen Architektur ist die kulturelle Bedeutung tiefgreifend. Das Museum war ausgezeichnet und die lokale Gemeinschaft so einladend!', '2024-08-15', 'de', true, 13, NOW(), NOW()),
('bk-de-003', 'bo-kaap-heritage-quarter', 'Klaus Weber', 'Hamburg, Deutschland', 'klaus.w@email.de', 4, 'Schöne und kulturell reiche Gegend. Die Kopfsteinpflasterstraßen und bunten Fassaden ergeben fantastische Fotos. Einige Bereiche können ziemlich touristisch werden.', '2024-08-08', 'de', true, 8, NOW(), NOW()),
('bk-de-004', 'bo-kaap-heritage-quarter', 'Sabine Fischer', 'Köln, Deutschland', 'sabine.f@email.de', 5, 'Unglaubliches kulturelles Eintauchen! Das Bo-Kaap Museum bot großartigen Kontext, und durch das Viertel zu gehen fühlte sich an wie ein Schritt in die lebende Geschichte. Das lokale Essen ist herausragend!', '2024-08-01', 'de', true, 11, NOW(), NOW()),
('bk-de-005', 'bo-kaap-heritage-quarter', 'Heinrich Müller', 'Frankfurt, Deutschland', 'heinrich.m@email.de', 4, 'Lebendige und historisch bedeutsame Gegend. Die Architektur ist atemberaubend und die Gemeinschaftsgeschichten bewegend. Kann mit Reisegruppen überfüllt werden.', '2024-07-25', 'de', true, 7, NOW(), NOW()),
('bk-de-006', 'bo-kaap-heritage-quarter', 'Andrea Schmidt', 'Stuttgart, Deutschland', 'andrea.s@email.de', 5, 'Phänomenale kulturelle Erfahrung! Die Erbe-Wanderung war aufschlussreich - so viel über die Kap-Malayische Gemeinschaft gelernt. Die traditionelle Architektur ist wunderschön erhalten.', '2024-07-18', 'de', true, 12, NOW(), NOW()),
('bk-de-007', 'bo-kaap-heritage-quarter', 'Wolfgang Becker', 'Düsseldorf, Deutschland', 'wolfgang.b@email.de', 5, 'Habe es absolut geliebt, dieses historische Viertel zu erkunden! Die bunten Häuser erzählen so wichtige Geschichten. Das Gewürzroute-Kocherlebnis war fantastisch!', '2024-07-11', 'de', true, 14, NOW(), NOW()),

-- French Reviews
('bk-fr-001', 'bo-kaap-heritage-quarter', 'Antoine Dubois', 'Paris, France', 'antoine.d@email.fr', 5, 'Quartier absolument magnifique! Les maisons colorées sont iconiques et lhistoire est fascinante. Notre guide était incroyablement connaisseur de la culture malaise du Cap. Le cours de cuisine était un point fort!', '2024-08-23', 'fr', true, 17, NOW(), NOW()),
('bk-fr-002', 'bo-kaap-heritage-quarter', 'Isabelle Martin', 'Lyon, France', 'isabelle.m@email.fr', 5, 'Un des endroits les plus photogéniques que jaie jamais visités! Au-delà de la belle architecture, la signification culturelle est profonde. Le musée était excellent!', '2024-08-16', 'fr', true, 12, NOW(), NOW()),
('bk-fr-003', 'bo-kaap-heritage-quarter', 'Pierre Rousseau', 'Marseille, France', 'pierre.r@email.fr', 4, 'Zone belle et culturellement riche. Les rues pavées et les façades colorées font des photos incroyables. Certaines zones peuvent devenir assez touristiques.', '2024-08-09', 'fr', true, 9, NOW(), NOW()),
('bk-fr-004', 'bo-kaap-heritage-quarter', 'Marie Leroy', 'Toulouse, France', 'marie.l@email.fr', 5, 'Immersion culturelle incroyable! Le musée Bo-Kaap a fourni un excellent contexte, et marcher dans le quartier ressemblait à entrer dans lhistoire vivante. La scène culinaire locale est exceptionnelle!', '2024-08-02', 'fr', true, 13, NOW(), NOW()),
('bk-fr-005', 'bo-kaap-heritage-quarter', 'Jean-Claude Bernard', 'Nice, France', 'jc.bernard@email.fr', 4, 'Zone vibrante et historiquement significative. Larchitecture est magnifique et les histoires communautaires sont émouvantes. Peut devenir bondé avec les groupes de touristes.', '2024-07-26', 'fr', true, 8, NOW(), NOW()),
('bk-fr-006', 'bo-kaap-heritage-quarter', 'Sylvie Moreau', 'Bordeaux, France', 'sylvie.m@email.fr', 5, 'Expérience culturelle phénoménale! La visite du patrimoine était éclairante - jai tant appris sur la communauté malaise du Cap. Larchitecture traditionnelle est magnifiquement préservée.', '2024-07-19', 'fr', true, 11, NOW(), NOW()),
('bk-fr-007', 'bo-kaap-heritage-quarter', 'François Petit', 'Strasbourg, France', 'francois.p@email.fr', 5, 'Jai absolument adoré explorer ce quartier historique! Les maisons colorées racontent des histoires si importantes. Lexpérience culinaire de la route des épices était fantastique!', '2024-07-12', 'fr', true, 15, NOW(), NOW()),

-- Spanish Reviews
('bk-es-001', 'bo-kaap-heritage-quarter', 'Roberto Martínez', 'Madrid, España', 'roberto.m@email.es', 5, '¡Barrio absolutamente impresionante! Las casas coloridas son icónicas y la historia es fascinante. Nuestro guía era increíblemente conocedor de la cultura malaya del Cabo. ¡La clase de cocina fue destacada!', '2024-08-24', 'es', true, 19, NOW(), NOW()),
('bk-es-002', 'bo-kaap-heritage-quarter', 'Carmen García', 'Barcelona, España', 'carmen.g@email.es', 5, '¡Uno de los lugares más fotogénicos que he visitado! Más allá de la hermosa arquitectura, el significado cultural es profundo. ¡El museo fue excelente y la comunidad local muy acogedora!', '2024-08-17', 'es', true, 14, NOW(), NOW()),
('bk-es-003', 'bo-kaap-heritage-quarter', 'Diego López', 'Valencia, España', 'diego.l@email.es', 4, 'Área hermosa y culturalmente rica. Las calles empedradas y fachadas coloridas hacen fotos increíbles. Algunas áreas pueden volverse bastante turísticas, pero las experiencias culturales auténticas valen la pena.', '2024-08-10', 'es', true, 10, NOW(), NOW()),
('bk-es-004', 'bo-kaap-heritage-quarter', 'Ana Fernández', 'Sevilla, España', 'ana.f@email.es', 5, '¡Inmersión cultural increíble! El Museo Bo-Kaap proporcionó gran contexto, y caminar por el barrio se sintió como entrar en la historia viva. ¡La escena gastronómica local es excepcional!', '2024-08-03', 'es', true, 12, NOW(), NOW()),
('bk-es-005', 'bo-kaap-heritage-quarter', 'Miguel Rodríguez', 'Bilbao, España', 'miguel.r@email.es', 4, 'Área vibrante e históricamente significativa. La arquitectura es impresionante y las historias comunitarias son conmovedoras. Puede llenarse de grupos turísticos, pero las visitas matutinas son más tranquilas.', '2024-07-27', 'es', true, 7, NOW(), NOW()),
('bk-es-006', 'bo-kaap-heritage-quarter', 'Laura Sánchez', 'Málaga, España', 'laura.s@email.es', 5, '¡Experiencia cultural fenomenal! El tour del patrimonio fue esclarecedor - aprendí mucho sobre la comunidad malaya del Cabo y su resistencia. La arquitectura tradicional está hermosamente preservada.', '2024-07-20', 'es', true, 13, NOW(), NOW()),
('bk-es-007', 'bo-kaap-heritage-quarter', 'Carlos Ruiz', 'Zaragoza, España', 'carlos.r@email.es', 5, '¡Absolutamente amé explorar este barrio histórico! Las casas coloridas cuentan historias tan importantes. La experiencia culinaria de la ruta de especias fue fantástica - gran manera de entender la cultura a través de la comida.', '2024-07-13', 'es', true, 16, NOW(), NOW()),

-- Arabic Reviews
('bk-ar-001', 'bo-kaap-heritage-quarter', 'حسام العبدالله', 'دبي، الإمارات', 'hussam.a@email.ae', 5, 'حي مذهل تماماً! البيوت الملونة مميزة والتاريخ مثير للاهتمام. دليلنا كان عارفاً بشكل لا يصدق عن الثقافة الملايوية في الكاب. كان درس الطبخ نقطة مضيئة - تعلمت الكثير عن التوابل والتقنيات التقليدية!', '2024-08-25', 'ar', true, 15, NOW(), NOW()),
('bk-ar-002', 'bo-kaap-heritage-quarter', 'نورا الشامي', 'الرياض، السعودية', 'nora.sh@email.sa', 5, 'واحد من أكثر الأماكن الجذابة للتصوير التي زرتها على الإطلاق! بعيداً عن الهندسة المعمارية الجميلة، الأهمية الثقافية عميقة. كان المتحف ممتازاً والمجتمع المحلي مرحب جداً!', '2024-08-18', 'ar', true, 12, NOW(), NOW()),
('bk-ar-003', 'bo-kaap-heritage-quarter', 'محمد الأحمد', 'الكويت، الكويت', 'mohammed.a@email.kw', 4, 'منطقة جميلة وغنية ثقافياً. الشوارع المرصوفة بالحصى والواجهات الملونة تجعل الصور مذهلة. بعض المناطق يمكن أن تصبح سياحية جداً، لكن التجارب الثقافية الأصيلة تستحق البحث عنها.', '2024-08-11', 'ar', true, 8, NOW(), NOW()),
('bk-ar-004', 'bo-kaap-heritage-quarter', 'فاطمة حسين', 'القاهرة، مصر', 'fatima.h@email.eg', 5, 'غمر ثقافي لا يصدق! متحف بو-كاب وفر سياقاً رائعاً، والمشي في الحي شعر وكأنه خطوة إلى التاريخ الحي. مشهد الطعام المحلي متميز - تلك الكويكسيسترز!', '2024-08-04', 'ar', true, 11, NOW(), NOW()),
('bk-ar-005', 'bo-kaap-heritage-quarter', 'عبدالله العلي', 'الدوحة، قطر', 'abdullah.alali@email.qa', 4, 'منطقة نابضة بالحياة ومهمة تاريخياً. الهندسة المعمارية مذهلة وقصص المجتمع مؤثرة. يمكن أن تكتظ بمجموعات سياحية، لكن الزيارات الصباحية الباكرة أكثر هدوءاً وأصالة.', '2024-07-28', 'ar', true, 6, NOW(), NOW()),
('bk-ar-006', 'bo-kaap-heritage-quarter', 'سارة البحريني', 'المنامة، البحرين', 'sara.b@email.bh', 5, 'تجربة ثقافية رائعة! جولة التراث كانت مفيدة - تعلمت الكثير عن مجتمع الملايو في الكاب ومقاومتهم. الهندسة المعمارية التقليدية محفوظة بشكل جميل.', '2024-07-21', 'ar', true, 13, NOW(), NOW()),
('bk-ar-007', 'bo-kaap-heritage-quarter', 'أحمد الزعبي', 'عمان، الأردن', 'ahmed.z@email.jo', 5, 'أحببت تماماً استكشاف هذا الحي التاريخي! البيوت الملونة تحكي قصصاً مهمة جداً. تجربة طبخ طريق التوابل كانت رائعة - طريقة رائعة لفهم الثقافة من خلال الطعام.', '2024-07-14', 'ar', true, 16, NOW(), NOW()),

-- CAPE TOWN SKYDIVE REVIEWS
-- English Reviews
('ct-en-001', 'cape-town-skydive', 'Jake Martinez', 'Miami, USA', 'jake.m@email.com', 5, 'ABSOLUTELY INCREDIBLE! The most exhilarating experience of my life! The views of Table Mountain and the coastline during freefall were breathtaking. The instructors were professional and made me feel completely safe. Worth every penny and every second of terror before jumping!', '2024-08-20', 'en', true, 22, NOW(), NOW()),
('ct-en-002', 'cape-town-skydive', 'Sophie Bennett', 'London, UK', 'sophie.b@email.com', 5, 'Best adrenaline rush ever! I was terrified before the jump but the tandem instructor was amazing and calming. The views of Cape Town from 10,000 feet are unmatched. The whole experience was incredibly well organized. Already planning to do it again!', '2024-08-13', 'en', true, 18, NOW(), NOW()),
('ct-en-003', 'cape-town-skydive', 'Michael Chen', 'Sydney, Australia', 'michael.c@email.com', 5, 'Words cannot describe this experience! The freefall over Cape Town was pure magic. Professional team, excellent safety briefing, and the views... WOW! Table Mountain looks incredible from above. This is a must-do bucket list item!', '2024-08-06', 'en', true, 20, NOW(), NOW()),
('ct-en-004', 'cape-town-skydive', 'Amanda Foster', 'Toronto, Canada', 'amanda.f@email.com', 4, 'Amazing experience but definitely not for the faint of heart! The jump itself was incredible and the views spectacular. Only downside was the wait due to weather conditions, but safety first. The team was very professional throughout.', '2024-07-30', 'en', true, 12, NOW(), NOW()),
('ct-en-005', 'cape-town-skydive', 'David Rodriguez', 'Denver, USA', 'david.r@email.com', 5, 'Life-changing experience! Facing my fear of heights was worth it for those 30 seconds of pure freedom. The Cape Town coastline from that height is something Ill never forget. Highly trained instructors and top-notch safety equipment.', '2024-07-23', 'en', true, 16, NOW(), NOW()),
('ct-en-006', 'cape-town-skydive', 'Emma Thompson', 'Manchester, UK', 'emma.t@email.com', 5, 'Phenomenal! The rush of jumping out of a plane over one of the worlds most beautiful cities is indescribable. The team made everything feel safe and exciting. The video package is definitely worth getting - youll want to relive this forever!', '2024-07-16', 'en', true, 19, NOW(), NOW()),
('ct-en-007', 'cape-town-skydive', 'Ryan Johnson', 'Melbourne, Australia', 'ryan.j@email.com', 4, 'Incredible views and amazing experience! The freefall felt longer than expected and the parachute ride down was peaceful and beautiful. Weather dependency can be frustrating but completely understand the safety precautions.', '2024-07-09', 'en', true, 11, NOW(), NOW()),
('ct-en-008', 'cape-town-skydive', 'Lisa Park', 'Vancouver, Canada', 'lisa.p@email.com', 5, 'Best thing Ive ever done! The fear before jumping quickly turned into pure exhilaration. Seeing Table Mountain, Lions Head, and the ocean from above was surreal. Professional operation with excellent safety standards. 10/10 would recommend!', '2024-07-02', 'en', true, 17, NOW(), NOW()),
('ct-en-009', 'cape-town-skydive', 'Tom Wilson', 'Dublin, Ireland', 'tom.w@email.com', 3, 'Good experience overall but quite expensive. The jump itself was thrilling and views were great. However, there were long delays and the briefing could have been more thorough. Still glad I did it but manage expectations on timing.', '2024-06-25', 'en', true, 6, NOW(), NOW()),

-- German Reviews
('ct-de-001', 'cape-town-skydive', 'Stefan Mueller', 'Berlin, Deutschland', 'stefan.m@email.de', 5, 'ABSOLUT UNGLAUBLICH! Das aufregendste Erlebnis meines Lebens! Die Aussicht auf den Tafelberg und die Küste während des freien Falls war atemberaubend. Die Instruktoren waren professionell und ließen mich völlig sicher fühlen!', '2024-08-21', 'de', true, 21, NOW(), NOW()),
('ct-de-002', 'cape-town-skydive', 'Petra Hoffmann', 'München, Deutschland', 'petra.h@email.de', 5, 'Bester Adrenalinstoß aller Zeiten! Ich hatte vor dem Sprung Angst, aber der Tandem-Instruktor war fantastisch und beruhigend. Die Aussicht auf Kapstadt aus 3000 Metern Höhe ist unübertroffen!', '2024-08-14', 'de', true, 17, NOW(), NOW()),
('ct-de-003', 'cape-town-skydive', 'Klaus Weber', 'Hamburg, Deutschland', 'klaus.w@email.de', 5, 'Worte können diese Erfahrung nicht beschreiben! Der freie Fall über Kapstadt war pure Magie. Professionelles Team, exzellentes Sicherheitsbriefing, und die Aussicht... WOW! Der Tafelberg sieht von oben unglaublich aus!', '2024-08-07', 'de', true, 19, NOW(), NOW()),
('ct-de-004', 'cape-town-skydive', 'Sabine Fischer', 'Köln, Deutschland', 'sabine.f@email.de', 4, 'Fantastisches Erlebnis, aber definitiv nichts für schwache Nerven! Der Sprung selbst war unglaublich und die Aussicht spektakulär. Einziger Nachteil war das Warten aufgrund der Wetterbedingungen.', '2024-07-31', 'de', true, 10, NOW(), NOW()),
('ct-de-005', 'cape-town-skydive', 'Heinrich Richter', 'Frankfurt, Deutschland', 'heinrich.r@email.de', 5, 'Lebensverändernde Erfahrung! Meine Höhenangst zu überwinden war es wert für diese 30 Sekunden pure Freiheit. Die Kapstädter Küstenlinie aus dieser Höhe werde ich nie vergessen!', '2024-07-24', 'de', true, 15, NOW(), NOW()),
('ct-de-006', 'cape-town-skydive', 'Andrea Schmidt', 'Stuttgart, Deutschland', 'andrea.s@email.de', 5, 'Phänomenal! Der Rausch, aus einem Flugzeug über eine der schönsten Städte der Welt zu springen, ist unbeschreiblich. Das Team machte alles sicher und aufregend. Das Video-Paket lohnt sich definitiv!', '2024-07-17', 'de', true, 18, NOW(), NOW()),
('ct-de-007', 'cape-town-skydive', 'Wolfgang Bauer', 'Düsseldorf, Deutschland', 'wolfgang.b@email.de', 4, 'Unglaubliche Aussicht und fantastisches Erlebnis! Der freie Fall fühlte sich länger an als erwartet und die Fallschirmfahrt nach unten war friedlich und schön. Wetterabhängigkeit kann frustrierend sein.', '2024-07-10', 'de', true, 9, NOW(), NOW()),

-- French Reviews
('ct-fr-001', 'cape-town-skydive', 'Antoine Dubois', 'Paris, France', 'antoine.d@email.fr', 5, 'ABSOLUMENT INCROYABLE! Lexpérience la plus exaltante de ma vie! Les vues de Table Mountain et du littoral pendant la chute libre étaient à couper le souffle. Les instructeurs étaient professionnels et mont fait me sentir complètement en sécurité!', '2024-08-22', 'fr', true, 23, NOW(), NOW()),
('ct-fr-002', 'cape-town-skydive', 'Marie Laurent', 'Lyon, France', 'marie.l@email.fr', 5, 'Meilleure montée dadrénaline jamais vécue! Jétais terrifiée avant le saut mais linstructeur tandem était incroyable et apaisant. Les vues du Cap depuis 3000 mètres sont inégalées!', '2024-08-15', 'fr', true, 16, NOW(), NOW()),
('ct-fr-003', 'cape-town-skydive', 'Jean-Pierre Martin', 'Marseille, France', 'jp.martin@email.fr', 5, 'Les mots ne peuvent décrire cette expérience! La chute libre au-dessus du Cap était de la pure magie. Équipe professionnelle, excellent briefing de sécurité, et les vues... WOW! Table Mountain est incroyable vue den haut!', '2024-08-08', 'fr', true, 20, NOW(), NOW()),
('ct-fr-004', 'cape-town-skydive', 'Sophie Rousseau', 'Toulouse, France', 'sophie.r@email.fr', 4, 'Expérience incroyable mais définitivement pas pour les âmes sensibles! Le saut lui-même était incroyable et les vues spectaculaires. Seul inconvénient était lattente due aux conditions météorologiques.', '2024-08-01', 'fr', true, 11, NOW(), NOW()),
('ct-fr-005', 'cape-town-skydive', 'Alain Bernard', 'Nice, France', 'alain.b@email.fr', 5, 'Expérience qui change la vie! Affronter ma peur des hauteurs en valait la peine pour ces 30 secondes de liberté pure. Le littoral du Cap depuis cette hauteur est quelque chose que je noublierai jamais!', '2024-07-25', 'fr', true, 14, NOW(), NOW()),
('ct-fr-006', 'cape-town-skydive', 'Isabelle Moreau', 'Bordeaux, France', 'isabelle.m@email.fr', 5, 'Phénoménal! Le frisson de sauter dun avion au-dessus dune des plus belles villes du monde est indescriptible. Léquipe a rendu tout sûr et excitant. Le package vidéo vaut définitivement le coup!', '2024-07-18', 'fr', true, 17, NOW(), NOW()),

-- Spanish Reviews
('ct-es-001', 'cape-town-skydive', 'Carlos Martínez', 'Madrid, España', 'carlos.m@email.es', 5, '¡ABSOLUTAMENTE INCREÍBLE! ¡La experiencia más emocionante de mi vida! Las vistas de Table Mountain y la costa durante la caída libre fueron impresionantes. Los instructores fueron profesionales y me hicieron sentir completamente seguro!', '2024-08-23', 'es', true, 24, NOW(), NOW()),
('ct-es-002', 'cape-town-skydive', 'Ana García', 'Barcelona, España', 'ana.g@email.es', 5, '¡La mejor descarga de adrenalina de todas! Estaba aterrorizada antes del salto pero el instructor tandem fue increíble y tranquilizador. Las vistas de Ciudad del Cabo desde 3000 metros son inigualables!', '2024-08-16', 'es', true, 18, NOW(), NOW()),
('ct-es-003', 'cape-town-skydive', 'Miguel López', 'Valencia, España', 'miguel.l@email.es', 5, '¡Las palabras no pueden describir esta experiencia! La caída libre sobre Ciudad del Cabo fue pura magia. Equipo profesional, excelente briefing de seguridad, y las vistas... ¡WOW! Table Mountain se ve increíble desde arriba!', '2024-08-09', 'es', true, 21, NOW(), NOW()),
('ct-es-004', 'cape-town-skydive', 'Laura Fernández', 'Sevilla, España', 'laura.f@email.es', 4, '¡Experiencia increíble pero definitivamente no para los débiles de corazón! El salto en sí fue increíble y las vistas espectaculares. El único inconveniente fue la espera debido a las condiciones climáticas.', '2024-08-02', 'es', true, 12, NOW(), NOW()),
('ct-es-005', 'cape-town-skydive', 'Diego Rodríguez', 'Bilbao, España', 'diego.r@email.es', 5, '¡Experiencia que cambia la vida! Enfrentar mi miedo a las alturas valió la pena por esos 30 segundos de libertad pura. La costa de Ciudad del Cabo desde esa altura es algo que nunca olvidaré!', '2024-07-26', 'es', true, 16, NOW(), NOW()),
('ct-es-006', 'cape-town-skydive', 'Carmen Sánchez', 'Málaga, España', 'carmen.s@email.es', 5, '¡Fenomenal! La emoción de saltar de un avión sobre una de las ciudades más hermosas del mundo es indescriptible. El equipo hizo que todo se sintiera seguro y emocionante. ¡El paquete de video definitivamente vale la pena!', '2024-07-19', 'es', true, 19, NOW(), NOW()),

-- Arabic Reviews
('ct-ar-001', 'cape-town-skydive', 'عمر الحسن', 'دبي، الإمارات', 'omar.h@email.ae', 5, 'لا يُصدق تماماً! التجربة الأكثر إثارة في حياتي! إطلالات جبل الطاولة والساحل أثناء السقوط الحر كانت خلابة. المدربون كانوا محترفين وجعلوني أشعر بالأمان التام. يستحق كل فلس وكل ثانية من الرعب قبل القفز!', '2024-08-24', 'ar', true, 20, NOW(), NOW()),
('ct-ar-002', 'cape-town-skydive', 'فاطمة محمد', 'الرياض، السعودية', 'fatima.m@email.sa', 5, 'أفضل اندفاع أدرينالين على الإطلاق! كنت مرعوبة قبل القفزة لكن المدرب التاندم كان مذهلاً ومهدئاً. إطلالات كيب تاون من 3000 متر لا مثيل لها. التجربة كاملة كانت منظمة بشكل لا يصدق!', '2024-08-17', 'ar', true, 15, NOW(), NOW()),
('ct-ar-003', 'cape-town-skydive', 'محمد الأحمد', 'الكويت، الكويت', 'mohammed.a@email.kw', 5, 'الكلمات لا تستطيع وصف هذه التجربة! السقوط الحر فوق كيب تاون كان سحراً خالصاً. فريق محترف، إحاطة أمنية ممتازة، والإطلالات... واو! جبل الطاولة يبدو لا يصدق من الأعلى!', '2024-08-10', 'ar', true, 18, NOW(), NOW()),
('ct-ar-004', 'cape-town-skydive', 'عائشة حسن', 'القاهرة، مصر', 'aisha.h@email.eg', 4, 'تجربة مذهلة لكن بالتأكيد ليست لضعاف القلوب! القفزة نفسها كانت لا تصدق والإطلالات مذهلة. العيب الوحيد كان الانتظار بسبب الأحوال الجوية، لكن الأمان أولاً.', '2024-08-03', 'ar', true, 9, NOW(), NOW()),
('ct-ar-005', 'cape-town-skydive', 'خالد العلي', 'الدوحة، قطر', 'khaled.a@email.qa', 5, 'تجربة تغير الحياة! مواجهة خوفي من المرتفعات كانت تستحق من أجل تلك الـ30 ثانية من الحرية الخالصة. ساحل كيب تاون من ذلك الارتفاع شيء لن أنساه أبداً!', '2024-07-27', 'ar', true, 17, NOW(), NOW()),
('ct-ar-006', 'cape-town-skydive', 'نورا الشامي', 'المنامة، البحرين', 'nora.sh@email.bh', 5, 'رائع! إثارة القفز من طائرة فوق واحدة من أجمل مدن العالم لا توصف. الفريق جعل كل شيء يبدو آمناً ومثيراً. حزمة الفيديو تستحق الحصول عليها بالتأكيد!', '2024-07-20', 'ar', true, 16, NOW(), NOW()),

