-- AQUILA SAFARI TOUR REVIEWS
-- English Reviews
('aq-en-001', 'aquila-safari-tour', 'John Anderson', 'Chicago, USA', 'john.a@email.com', 5, 'Absolutely phenomenal safari experience! Saw the Big 5 including incredible close encounters with elephants and lions. Our game ranger was incredibly knowledgeable and passionate. The drive through the African bush was magical. Best day of our South Africa trip!', '2024-08-19', 'en', true, 25, NOW(), NOW()),
('aq-en-002', 'aquila-safari-tour', 'Emma Wilson', 'London, UK', 'emma.w@email.com', 5, 'Outstanding safari adventure! The wildlife viewing was exceptional - saw rhinos, giraffes, and a pride of lions. The breakfast in the bush was a lovely touch. Professional guides who really care about conservation. Highly recommend!', '2024-08-12', 'en', true, 19, NOW(), NOW()),
('aq-en-003', 'aquila-safari-tour', 'Mark Thompson', 'Sydney, Australia', 'mark.t@email.com', 4, 'Great safari experience with amazing animal sightings. The game drive was exciting and educational. Only downside was the early morning pickup, but worth it for cooler temperatures and active wildlife. The lunch was excellent too!', '2024-08-05', 'en', true, 13, NOW(), NOW()),
('aq-en-004', 'aquila-safari-tour', 'Sarah Davis', 'Toronto, Canada', 'sarah.d@email.com', 5, 'Incredible day in the African wilderness! The variety of animals we saw was amazing - elephants, buffalo, zebras, and so many bird species. Our guide made the experience educational and fun. The reserve is well-maintained and beautiful.', '2024-07-29', 'en', true, 16, NOW(), NOW()),
('aq-en-005', 'aquila-safari-tour', 'David Miller', 'New York, USA', 'david.m@email.com', 5, 'Best wildlife experience of my life! The thrill of seeing wild African animals in their natural habitat is indescribable. Professional operation with excellent guides. The conservation message was inspiring. Will definitely return!', '2024-07-22', 'en', true, 18, NOW(), NOW()),
('aq-en-006', 'aquila-safari-tour', 'Lisa Johnson', 'Melbourne, Australia', 'lisa.j@email.com', 4, 'Wonderful safari with great animal encounters. The elephants were the highlight - so majestic! Guide was very informative about animal behavior and conservation efforts. Could have spent longer on the game drive but overall fantastic.', '2024-07-15', 'en', true, 11, NOW(), NOW()),
('aq-en-007', 'aquila-safari-tour', 'Robert Brown', 'Dublin, Ireland', 'robert.b@email.com', 5, 'Absolutely magical experience! Seeing lions, rhinos, and elephants up close was surreal. The game ranger was fantastic - so knowledgeable and passionate about wildlife. The scenic drive to the reserve was beautiful too. Unforgettable!', '2024-07-08', 'en', true, 20, NOW(), NOW()),
('aq-en-008', 'aquila-safari-tour', 'Jennifer Lee', 'Vancouver, Canada', 'jennifer.l@email.com', 4, 'Great safari adventure! Loved seeing all the different animals and learning about their behaviors. The bush breakfast was a nice touch. Weather was perfect and our guide was excellent. Would recommend to anyone visiting Cape Town.', '2024-07-01', 'en', true, 14, NOW(), NOW()),
('aq-en-009', 'aquila-safari-tour', 'Michael Garcia', 'Los Angeles, USA', 'michael.g@email.com', 3, 'Good safari experience but quite commercialized. Saw some great animals but felt a bit rushed. The facilities are nice and lunch was good. Still enjoyable but not as authentic as I hoped for. Better for first-time safari goers.', '2024-06-24', 'en', true, 7, NOW(), NOW()),

